(()=>{
'use strict';
if(window.__bamcoAdminRootFixes20260911V11)return;
window.__bamcoAdminRootFixes20260911V11=true;
const q=(s,r=document)=>r?.querySelector?.(s)||null,qa=(s,r=document)=>[...(r?.querySelectorAll?.(s)||[])];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const faNum=v=>typeof fa==='function'?fa(v):String(v??'').replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
const deadSelector='[data-view="templates"],[data-view="messageTemplates"],#templatesView,#messageTemplatesView,#desktopTemplateEditor,#openDesktopTemplateEditor,#templateBody,#templateState,#saveTemplateBtn,[data-message-text-section],.message-text-section,.message-custom-text,.custom-message-text';
function isMessageTextLabel(el){const t=(el?.textContent||'').replace(/\s+/g,' ').trim();return /(?:^|\s)(?:متن\s*پیام(?:‌|\s)*(?:ها)?|ویرایش\s*متن\s*پیام)(?:$|\s)/i.test(t)}
function purgeMessageTextUi(root=document){qa(deadSelector,root).forEach(x=>x.remove());qa('#nav button,#nav a,.nav-group-items>button,.nav-group-items>a',root===document?document:root).filter(isMessageTextLabel).forEach(x=>x.remove());const custom=q('#messageCustomText',root===document?document:root);if(custom)(custom.closest('[data-message-text-section],.message-text-section,.message-custom-text,.custom-message-text')||custom.closest('label')||custom).remove();qa('#messageCenterView button,#messageCenterView a,#messageCenterView [role="tab"],#messageCenterView .tab',root===document?document:root).filter(isMessageTextLabel).forEach(x=>x.remove());if(typeof state!=='undefined'&&(state.view==='templates'||state.view==='messageTemplates')){if(typeof window.bamcoShowHome==='function')window.bamcoShowHome();else if(typeof showView==='function')showView('messageCenter')}}
function addedNodeNeedsPurge(node){if(node?.nodeType!==1)return false;return node.matches?.(deadSelector)||node.querySelector?.(deadSelector)||isMessageTextLabel(node.matches?.('#nav button,#nav a,#messageCenterView button,#messageCenterView a,#messageCenterView [role="tab"],#messageCenterView .tab')?node:null)}
function installMessageTextPurge(){purgeMessageTextUi();if(document.body&&!document.body.dataset.messageTextPurge){document.body.dataset.messageTextPurge='5';let queued=false;new MutationObserver(records=>{if(!records.some(r=>[...r.addedNodes].some(addedNodeNeedsPurge))||queued)return;queued=true;queueMicrotask(()=>{queued=false;purgeMessageTextUi()})}).observe(document.body,{childList:true,subtree:true})}document.addEventListener('click',e=>{const dead=e.target.closest?.('[data-view="templates"],[data-view="messageTemplates"],#openDesktopTemplateEditor,#saveTemplateBtn');if(!dead&&!isMessageTextLabel(e.target.closest?.('#nav button,#nav a,#messageCenterView button,#messageCenterView a,#messageCenterView [role="tab"],#messageCenterView .tab')))return;e.preventDefault();e.stopImmediatePropagation();purgeMessageTextUi()},true)}
function normalizeRequestExport(){const b=q('#requestReportView [data-report-export]');if(b&&b.textContent!=='خروجی اکسل')b.textContent='خروجی اکسل'}
function installRequestGuard(){normalizeRequestExport();const view=q('#requestReportView');if(view&&!view.dataset.rootRequestWatch){view.dataset.rootRequestWatch='5';new MutationObserver(records=>{if(records.some(r=>r.addedNodes.length))normalizeRequestExport()}).observe(view,{childList:true,subtree:true})}document.addEventListener('click',e=>{if(e.target.closest('#nav [data-view="requestReport"]'))setTimeout(normalizeRequestExport,40)},true)}
function enforceActiveView(id){if(!id||typeof state==='undefined'||state.view!==id)return;const target=q('#'+id+'View');if(!target)return;qa('#appView .view,.workspace > .view').forEach(v=>v.classList.toggle('hidden',v!==target));target.classList.remove('hidden');qa('#nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id))}
function installNavigationInvariant(){document.addEventListener('click',e=>{const b=e.target.closest?.('#nav button[data-view]');if(!b||b.disabled)return;const id=b.dataset.view;queueMicrotask(()=>enforceActiveView(id));requestAnimationFrame(()=>enforceActiveView(id));setTimeout(()=>enforceActiveView(id),120)},false)}
function setTaskToolbar(scope,picked){for(const suffix of ['EditBtn','DeleteBtn'])q(`#${scope}${suffix}`)?.toggleAttribute('disabled',!picked);if(scope==='kanban')q('#kanbanArchiveBtn')?.toggleAttribute('disabled',!picked);else q('#archiveRestoreBtn')?.toggleAttribute('disabled',!picked)}
function selectTaskRow(row){const scope=row.dataset.scope,id=String(row.dataset.taskId||'');if(!scope||!id||typeof state==='undefined')return;state.selected[scope]=Number(id);const body=q(scope==='archive'?'#archiveBody':'#kanbanBody');qa('tr[data-task-id]',body).forEach(r=>{const yes=String(r.dataset.taskId)===id;r.classList.toggle('task-selected',yes);const radio=q('.task-pick',r);if(radio)radio.checked=yes});window.bamcoSelection?.set?.(body,[id]);setTaskToolbar(scope,true)}
function installFastTaskSelection(){document.addEventListener('click',e=>{const row=e.target.closest?.('#kanbanBody tr[data-task-id],#archiveBody tr[data-task-id]');if(!row||e.target.closest('button,a,select,textarea'))return;e.preventDefault();e.stopImmediatePropagation();selectTaskRow(row)},true)}

/* ---------- comprehensive sent messages center ---------- */
const SENT_STATUS={queued:'در صف',processing:'در حال ارسال',sent:'ارسال‌شده',delivered:'تحویل‌شده',failed:'خطا',cancelled:'لغوشده',ready:'آماده'};
const SENT_CHANNEL={portal:'داخل سامانه',email:'ایمیل',both:'هر دو'};
let sentRows=[],sentSnapshots=new Map(),sentLoading=null;
const sentDate=v=>v&&Number.isFinite(Date.parse(v))?(typeof jalaliDateTime==='function'?jalaliDateTime(v):new Date(v).toLocaleString('fa-IR')):'—';
function sentPerson(id){const p=(state.profiles||[]).find(x=>String(x.id)===String(id));return p?.display_name||p?.full_name||p?.email||'—'}
function ensureSentNav(){let b=q('#nav button[data-view="sentMessages"]');if(!b){b=document.createElement('button');b.type='button';b.dataset.view='sentMessages';b.className='manager-only';b.innerHTML='<b>✓</b><span>پیام‌های ارسال‌شده</span>';const group=q('#nav .nav-group[data-group="messages"] .nav-group-items');(group||q('#nav'))?.append(b)}b.classList.add('manager-only');b.classList.toggle('hidden',typeof isManager==='function'&&!isManager());return b}
function ensureSentView(){let view=q('#sentMessagesView');if(!view){view=document.createElement('section');view.id='sentMessagesView';view.className='view hidden manager-only';q('.workspace')?.append(view)}return view}
function installSentCss(){if(q('#bamcoSentMessagesCss'))return;const s=document.createElement('style');s.id='bamcoSentMessagesCss';s.textContent=`
#sentMessagesView .sent-overview{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px;margin:10px 0 14px}#sentMessagesView .sent-overview article{border:1px solid #d6e2dc;border-radius:12px;background:#f8fbf9;padding:11px 13px}#sentMessagesView .sent-overview small{display:block;color:#70837a;margin-bottom:4px}#sentMessagesView .sent-overview strong{font-size:22px;color:#165c45}#sentMessagesView .sent-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:10px 0 12px}#sentMessagesView .sent-controls input[type=search]{min-width:220px;flex:1}#sentMessagesView .sent-controls select{min-width:135px}#sentMessagesView .sent-table tbody tr{cursor:pointer}#sentMessagesView .sent-table td.sent-error{max-width:240px;white-space:normal;color:#a33}#sentMessagesView .sent-status{display:inline-block;border-radius:999px;padding:2px 8px;border:1px solid #d0ddd7;background:#f5f8f6;white-space:nowrap}#sentMessagesView .sent-status.failed{background:#fff1f0;border-color:#efbbb7;color:#9d342e}#sentMessagesView .sent-status.delivered,#sentMessagesView .sent-status.sent{background:#edf8f2;border-color:#b9dcc8;color:#1c6a4d}#sentMessagesView .sent-status.queued,#sentMessagesView .sent-status.processing{background:#fff8df;border-color:#ead58e;color:#806514}#sentMessageDetail{width:min(1000px,94vw);max-height:90vh;border:1px solid #bfd1c8;border-radius:18px;padding:0;overflow:hidden}#sentMessageDetail::backdrop{background:#244b3e78;backdrop-filter:blur(3px)}#sentMessageDetail .sent-detail-body{padding:18px 22px;overflow:auto;max-height:calc(90vh - 74px)}#sentMessageDetail .sent-detail-meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-bottom:14px}#sentMessageDetail .sent-detail-meta div{border:1px solid #dce7e2;border-radius:10px;padding:9px 11px;background:#f8fbf9}#sentMessageDetail .sent-detail-meta small{display:block;color:#70837a}#sentMessageDetail .sent-detail-text{white-space:pre-wrap;border:1px solid #dce7e2;border-radius:12px;padding:14px;background:#fff;line-height:1.9}@media(max-width:800px){#sentMessagesView .sent-overview{grid-template-columns:repeat(2,minmax(0,1fr))}#sentMessageDetail .sent-detail-meta{grid-template-columns:1fr}#sentMessagesView .sent-controls>*{max-width:100%}}
`;document.head.append(s)}
function sentFiltered(){const search=(q('#sentSearch')?.value||'').trim().toLocaleLowerCase(),status=q('#sentStatusFilter')?.value||'',channel=q('#sentChannelFilter')?.value||'';return sentRows.filter(d=>{const s=sentSnapshots.get(String(d.snapshot_id))||{},hay=[d.id,s.recipient_name,s.recipient_email,s.subject,d.thread_key,d.error_message,s.sender_name,s.sender_name_snapshot].map(v=>String(v||'').toLocaleLowerCase()).join(' ');return(!search||hay.includes(search))&&(!status||d.status===status)&&(!channel||d.channel===channel)})}
function renderSent(){const view=ensureSentView(),filtered=sentFiltered(),success=sentRows.filter(d=>['sent','delivered'].includes(d.status)).length,waiting=sentRows.filter(d=>['queued','processing','ready'].includes(d.status)).length,failed=sentRows.filter(d=>d.status==='failed').length,delivered=sentRows.filter(d=>d.status==='delivered').length;view.innerHTML=`<div class="panel workspace-panel"><div class="panel-head"><div><h3>پیام‌های ارسال‌شده</h3><small>سابقه کامل ارسال‌های داخل سامانه و ایمیل، وضعیت تحویل و خطاها</small></div><div class="workspace-actions"><button type="button" class="ghost" data-sent-refresh>تازه‌سازی</button><button type="button" class="ghost" data-sent-export>خروجی اکسل</button><button type="button" class="ghost content-back">⌂ خانه</button></div></div><div class="sent-overview"><article><small>کل مسیرهای ارسال</small><strong>${faNum(sentRows.length)}</strong></article><article><small>ارسال موفق</small><strong>${faNum(success)}</strong></article><article><small>تحویل‌شده</small><strong>${faNum(delivered)}</strong></article><article><small>در صف / پردازش</small><strong>${faNum(waiting)}</strong></article><article><small>خطا</small><strong>${faNum(failed)}</strong></article></div><div class="sent-controls"><input id="sentSearch" type="search" placeholder="جست‌وجوی گیرنده، موضوع، شناسه یا خطا…" value="${esc(q('#sentSearch')?.value||'')}"><select id="sentStatusFilter"><option value="">همه وضعیت‌ها</option>${Object.entries(SENT_STATUS).map(([v,l])=>`<option value="${v}" ${q('#sentStatusFilter')?.value===v?'selected':''}>${l}</option>`).join('')}</select><select id="sentChannelFilter"><option value="">همه کانال‌ها</option>${Object.entries(SENT_CHANNEL).map(([v,l])=>`<option value="${v}" ${q('#sentChannelFilter')?.value===v?'selected':''}>${l}</option>`).join('')}</select><span>${faNum(filtered.length)} رکورد نمایش داده می‌شود</span></div><div class="table-wrap"><table class="workspace-table sent-table"><thead><tr><th>شناسه</th><th>فرستنده</th><th>گیرنده</th><th>موضوع</th><th>کانال</th><th>وضعیت</th><th>زمان ایجاد</th><th>زمان ارسال</th><th>تلاش</th><th>خطا</th><th>شناسه پیگیری</th><th>جزئیات</th></tr></thead><tbody>${filtered.length?filtered.map(d=>{const s=sentSnapshots.get(String(d.snapshot_id))||{},sender=s.sender_name||s.sender_name_snapshot||sentPerson(d.created_by||d.sender_id),recipient=s.recipient_name||sentPerson(d.recipient_id);return`<tr data-sent-id="${esc(d.id)}" data-snapshot-id="${esc(d.snapshot_id||'')}"><td>${faNum(d.id)}</td><td>${esc(sender)}</td><td>${esc(recipient)}</td><td>${esc(s.subject||'—')}</td><td>${esc(SENT_CHANNEL[d.channel]||d.channel||'—')}</td><td><span class="sent-status ${esc(d.status||'')}">${esc(SENT_STATUS[d.status]||d.status||'—')}</span></td><td>${esc(sentDate(d.created_at))}</td><td>${esc(sentDate(d.sent_at||d.delivered_at))}</td><td>${faNum(d.attempt_count||0)}</td><td class="sent-error">${esc(d.error_message||'—')}</td><td class="english" dir="ltr">${esc(d.thread_key||'—')}</td><td><button type="button" class="ghost" data-sent-detail="${esc(d.id)}">مشاهده</button></td></tr>`}).join(''):'<tr><td colspan="12" class="empty">رکوردی مطابق فیلترها وجود ندارد.</td></tr>'}</tbody></table></div></div>`;bindSentControls()}
function bindSentControls(){q('#sentSearch')?.addEventListener('input',renderSent);q('#sentStatusFilter')?.addEventListener('change',renderSent);q('#sentChannelFilter')?.addEventListener('change',renderSent);q('[data-sent-refresh]')?.addEventListener('click',()=>void loadSent(true));q('[data-sent-export]')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{const table=q('#sentMessagesView table');if(!window.bamcoExportTable)throw Error('امکانات خروجی اکسل هنوز بارگذاری نشده است.');await window.bamcoExportTable(table)}catch(err){toast(err.message,true)}finally{b.disabled=false}});q('#sentMessagesView .content-back')?.addEventListener('click',()=>window.bamcoShowHome?.());qa('[data-sent-detail]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openSentDetail(b.dataset.sentDetail)}));qa('#sentMessagesView tr[data-sent-id]').forEach(r=>r.addEventListener('dblclick',()=>openSentDetail(r.dataset.sentId)))}
function ensureSentDialog(){let d=q('#sentMessageDetail');if(!d){d=document.createElement('dialog');d.id='sentMessageDetail';d.className='modal';document.body.append(d)}return d}
function openSentDetail(id){const d=sentRows.find(x=>String(x.id)===String(id));if(!d)return;const s=sentSnapshots.get(String(d.snapshot_id))||{},dialog=ensureSentDialog(),sender=s.sender_name||s.sender_name_snapshot||sentPerson(d.created_by||d.sender_id),recipient=s.recipient_name||sentPerson(d.recipient_id),body=s.final_text||s.body||s.body_template||'';let preview='';try{if(window.BamcoMessageRender?.html)preview=BamcoMessageRender.html(s,{subject:s.subject,reportDate:s.created_at,senderName:sender})}catch{}dialog.innerHTML=`<div class="modal-head"><div><h3>جزئیات پیام ارسال‌شده</h3><p>${esc(s.subject||'بدون موضوع')}</p></div><button type="button" class="clean-close" aria-label="بستن">×</button></div><div class="sent-detail-body"><div class="sent-detail-meta"><div><small>شناسه ارسال</small><b>${faNum(d.id)}</b></div><div><small>فرستنده</small><b>${esc(sender)}</b></div><div><small>گیرنده</small><b>${esc(recipient)}</b></div><div><small>کانال</small><b>${esc(SENT_CHANNEL[d.channel]||d.channel||'—')}</b></div><div><small>وضعیت</small><b>${esc(SENT_STATUS[d.status]||d.status||'—')}</b></div><div><small>زمان ارسال</small><b>${esc(sentDate(d.sent_at||d.created_at))}</b></div><div><small>تعداد تلاش</small><b>${faNum(d.attempt_count||0)}</b></div><div><small>شناسه پیگیری</small><b class="english" dir="ltr">${esc(d.thread_key||'—')}</b></div><div><small>خطا</small><b>${esc(d.error_message||'بدون خطا')}</b></div></div>${preview?`<div class="message-report-body">${preview}</div>`:`<div class="sent-detail-text">${esc(body||'متن ثبت‌شده‌ای در دسترس نیست.')}</div>`}</div>`;q('.clean-close',dialog).onclick=()=>dialog.close();dialog.showModal()}
function activateSentView(){if(typeof isManager==='function'&&!isManager())return;const view=ensureSentView();window.bamcoLeaveHome?.();if(typeof state!=='undefined')state.view='sentMessages';document.body.classList.remove('welcome-active','card-home-active');document.body.classList.add('content-only');q('#welcomeView')?.classList.add('hidden');qa('#appView .view,.workspace > .view').forEach(v=>v.classList.toggle('hidden',v!==view));view.classList.remove('hidden','bamco-view-settling');qa('#nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='sentMessages'));const title=q('#viewTitle');if(title)title.textContent='پیام‌های ارسال‌شده';q('#addTaskBtn')?.classList.add('hidden');void loadSent()}
function loadSent(force=false){if(sentLoading&&!force)return sentLoading;const view=ensureSentView();view.classList.add('bamco-view-settling');if(!view.querySelector('.sent-overview'))view.innerHTML='<div class="panel"><p class="workspace-loading" role="status">در حال دریافت سابقه پیام‌ها…</p></div>';sentLoading=(async()=>{try{const [deliveries,snapshots]=await Promise.all([selectAll('message_deliveries','select=*&order=created_at.desc'),selectAll('message_snapshots','select=*&order=id.desc')]);sentRows=deliveries||[];sentSnapshots=new Map((snapshots||[]).map(s=>[String(s.id),s]));if(typeof state==='undefined'||state.view==='sentMessages')renderSent()}catch(err){view.innerHTML=`<div class="panel"><div class="workspace-error" role="alert"><b>سابقه پیام‌ها دریافت نشد.</b><p>${esc(err.message)}</p><button type="button" class="ghost" data-sent-retry>تلاش دوباره</button></div></div>`;q('[data-sent-retry]',view)?.addEventListener('click',()=>void loadSent(true))}finally{view.classList.remove('bamco-view-settling');view.dispatchEvent(new CustomEvent('bamco-view-data-ready',{bubbles:true}));sentLoading=null}})();return sentLoading}
function installSentMessages(){installSentCss();ensureSentNav();ensureSentView();document.addEventListener('click',e=>{const nav=e.target.closest?.('#nav button[data-view="sentMessages"]');if(!nav||nav.disabled)return;e.preventDefault();e.stopImmediatePropagation();activateSentView()},true);window.bamcoSentMessages={open:activateSentView,refresh:()=>loadSent(true)}}

function boot(){installRequestGuard();installMessageTextPurge();installNavigationInvariant();installFastTaskSelection();installSentMessages();normalizeRequestExport()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
